/\ cycleFirst' = nextSeq
/\ cycleStarts' = cycleStarts \cup {nextSeq}
/\ out' = (IF turnOpen /\ heldFirst < nextSeq THEN <<[kind |-> "drop", from |-> heldFirst, to |-> nextSeq]>> ELSE <<>>) /\ act' = [name |-> "Compacted"]

core.find:
var next = state;
next.turn_open = false;
return .{ .state = next };

core.replace:
var next = state;
next.turn_open = false;
if (next.held_first < next.next_seq) {
    const from = next.held_first;
    next.held_first = next.next_seq;
    return .{ .state = next, .effect = .{ .drop = .{ .from = from, .to = next.next_seq } } };
}
return .{ .state = next };

core.find:
next.cycle = state.cycle + 1;
next.cycle_first = state.next_seq;
return .{ .state = next };

core.replace:
next.cycle = state.cycle + 1;
next.cycle_first = state.next_seq;
next.held_first = state.next_seq;
return .{ .state = next };

core.find:
return .{
    .state = State.init(state.config),
    .effect = if (from < to) .{ .drop = .{ .from = from, .to = to } } else null,
};

if (co.lo > held_first) return show(state, co.lo - 1, @min(co.hi, co.lo - 1 + window));
if (state.config.saved) return issueRead(state, .older, co.lo);
var next = state;
next.ctrlo.at_start = true;
return .{ .state = next };

core.replace:
var next = state;
next.reprinting = true;
return .{ .state = next, .effect = .{ .repaint_block = id } };
